T_1\paren{\left[\begin{array}{c} x \\ y \end{array}\right]}
  = \left[\begin{array}{c} x^2 \\ x+y \\ y^2 \end{array}\right],\quad
  T_2\paren{\left[\begin{array}{c} x \\ y \\ z \end{array}\right]}
  = \left[\begin{array}{c} x+y \\ x+y+z \\ 0 \end{array}\right],\quad
  T_3\paren{\left[\begin{array}{c} x \\ y \\ z \end{array}\right]}
  = \left[\begin{array}{c} e^{x+z} \\ \sqrt{y} \end{array}\right]. \tag{1}

